  _k('kgeo-026', 'geometri', 'Katı Cisimler', 'Prizma ve silindir', 'Hacim = Taban alanı · Yükseklik\nSilindir: V = πr²h, yanal alan = 2πrh', 'Taban × yükseklik'),
  _k('kgeo-027', 'geometri', 'Katı Cisimler', 'Piramit ve koni', 'Hacim = (Taban alanı · Yükseklik) / 3\nKoni: V = πr²h / 3', 'Prizmanın üçte biri'),
  _k('kgeo-028', 'geometri', 'Katı Cisimler', 'Küre', 'Hacim = (4/3)πr³\nYüzey alanı = 4πr²', '4 büyük daire alanı'),
  _k('kgeo-029', 'geometri', 'Katı Cisimler', 'Küp ve dikdörtgenler prizması', 'Küp: hacim a³, yüzey 6a², cisim köşegeni a√3\nDikdörtgenler prizması: hacim abc, cisim köşegeni √(a² + b² + c²)', 'a√3'),

  // ─── FİZİK ─────────────────────────────────────────────
  _k('kfiz-001', 'fizik', 'Fizik Bilimine Giriş', 'Skaler ve vektörel büyüklükler', 'Skaler: yalnızca büyüklüğü olan (kütle, zaman, sıcaklık, enerji, sürat).\nVektörel: büyüklük ve yönü olan (kuvvet, hız, ivme, yer değiştirme, momentum).', 'Yön var mı?'),
  _k('kfiz-002', 'fizik', 'Hareket', 'Sürat ile hız farkı', 'Sürat = alınan toplam yol / zaman (skaler)\nHız = yer değiştirme / zaman (vektörel)\nBaşladığı yere dönen cismin ortalama hızı sıfırdır.', 'Yol vs yer değiştirme'),
  _k('kfiz-003', 'fizik', 'Hareket', 'Düzgün hızlanan hareket denklemleri', 'v = v₀ + a·t\nx = v₀·t + ½·a·t²\nv² = v₀² + 2·a·x', 'Zamansız hız denklemi'),
  _k('kfiz-004', 'fizik', 'Hareket', 'Serbest düşme', 'Hava direnci yoksa tüm cisimler aynı ivmeyle (g) düşer.\nv = g·t, h = ½·g·t², v² = 2gh', 'Kütleden bağımsız'),
  _k('kfiz-005', 'fizik', 'Hareket', 'Yatay atış', 'Yatayda sabit hız (vₓ = v₀), düşeyde serbest düşme.\nMenzil = v₀ · t, uçuş süresi yalnızca yüksekliğe bağlıdır: t = √(2h/g)', 'Yatay sabit, düşey serbest'),
  _k('kfiz-006', 'fizik', 'Kuvvet', 'Newton\'un III. yasası', 'Etki-tepki: A cismi B\'ye kuvvet uygularsa B de A\'ya eşit büyüklükte, zıt yönde kuvvet uygular. Kuvvetler farklı cisimlere etki ettiği için birbirini dengelemez.', 'Farklı cisimler'),
  _k('kfiz-007', 'fizik', 'Kuvvet', 'Sürtünme kuvveti', 'fₛ = k · N (k: sürtünme katsayısı, N: tepki kuvveti)\nHareket yönüne zıttır; yüzey alanına bağlı değildir. Statik sürtünme, kinetik sürtünmeden büyüktür.', 'Alana bağlı değil'),
  _k('kfiz-008', 'fizik', 'Enerji', 'İş', 'W = F · x · cos θ\nKuvvet yer değiştirmeye dikse iş yapılmaz.\nBirimi joule (J) = N·m', 'Dik kuvvet iş yapmaz'),
  _k('kfiz-009', 'fizik', 'Enerji', 'Mekanik enerjinin korunumu', 'Sürtünmesiz ortamda E_k + E_p sabittir.\nE_k = ½mv², E_p = mgh\nSürtünme varsa kaybolan enerji ısıya dönüşür.', 'Kinetik + potansiyel sabit'),
  _k('kfiz-010', 'fizik', 'Enerji', 'Güç ve verim', 'P = W / t (birimi watt)\nVerim = (Yararlı enerji / Harcanan enerji) · 100', 'İş / zaman'),
  _k('kfiz-011', 'fizik', 'Basınç', 'Katı ve sıvı basıncı', 'Katı: P = F / A\nSıvı: P = h · d · g (kabın şekline bağlı değil)\nAçık hava basıncı deniz seviyesinde ≈ 76 cmHg', 'Derinlik × özkütle × g'),
  _k('kfiz-012', 'fizik', 'Basınç', 'Pascal ilkesi', 'Kapalı kaptaki sıvıya uygulanan basınç, sıvının her noktasına aynen iletilir.\nHidrolik fren ve kriko bu ilkeyle çalışır: F₁ / A₁ = F₂ / A₂', 'Hidrolik kriko'),
  _k('kfiz-013', 'fizik', 'Kaldırma Kuvveti', 'Arşimet ilkesi ve yüzme koşulu', 'F_k = V_batan · d_sıvı · g\nCisim yüzüyorsa F_k = ağırlık.\nd_cisim < d_sıvı ⟹ yüzer, eşitse askıda kalır, büyükse batar.', 'Taşan sıvının ağırlığı'),
  _k('kfiz-014', 'fizik', 'Isı ve Sıcaklık', 'Isı ve hâl değişimi', 'Sıcaklık değişimi: Q = m · c · ΔT\nHâl değişimi: Q = m · L (sıcaklık sabit kalır)\nIsı sıcaklığı yüksek cisimden düşük cisme akar.', 'Hâl değişiminde T sabit'),
  _k('kfiz-015', 'fizik', 'Isı ve Sıcaklık', 'Isı yayılma yolları', 'İletim: katılarda tanecikler arası (metal kaşık ısınması)\nKonveksiyon (taşıma): akışkanlarda madde hareketiyle\nIşıma: boşlukta da gerçekleşir (Güneş ısısı)', 'Işıma boşlukta'),
  _k('kfiz-016', 'fizik', 'Elektrostatik', 'Coulomb yasası', 'F = k · q₁ · q₂ / d²\nAynı işaretli yükler iter, zıt işaretliler çeker. Kuvvet uzaklığın karesiyle ters orantılıdır.', 'Uzaklığın karesi'),
  _k('kfiz-017', 'fizik', 'Elektrik', 'Akım ve Ohm yasası', 'I = q / t (amper)\nV = I · R\nİletkenin direnci: R = ρ · L / A (boyla doğru, kesitle ters orantılı)', 'Uzun ince tel direnci büyük'),
  _k('kfiz-018', 'fizik', 'Elektrik', 'Seri ve paralel bağlama', 'Seri: R_eş = R₁ + R₂ + …, akım her dirençte aynı\nParalel: 1/R_eş = 1/R₁ + 1/R₂ + …, gerilim her kolda aynı', 'Seri akım, paralel gerilim'),
  _k('kfiz-019', 'fizik', 'Elektrik', 'Elektriksel güç ve enerji', 'P = V · I = I² · R = V² / R\nEnerji: E = P · t (kWh = 3,6 · 10⁶ J)', 'P = VI'),
  _k('kfiz-020', 'fizik', 'Manyetizma', 'Elektromanyetik indüksiyon', 'Bir iletkenden geçen manyetik akı değişirse iletkende indüksiyon akımı oluşur (Faraday).\nLenz kuralı: indüksiyon akımı, kendisini oluşturan değişime karşı koyar.\nJeneratör ve transformatör bu ilkeyle çalışır.', 'Akı değişimi → akım'),
  _k('kfiz-021', 'fizik', 'Dalgalar', 'Dalga denklemi', 'v = λ · f\nFrekans kaynağa bağlıdır, ortam değişince değişmez.\nHız ortama bağlıdır; derin suda su dalgası daha hızlıdır.', 'Frekans sabit'),
  _k('kfiz-022', 'fizik', 'Optik', 'Işığın kırılması (Snell yasası)', 'n₁ · sin θ₁ = n₂ · sin θ₂\nAz yoğun ortamdan çok yoğun ortama geçen ışın normale yaklaşır.\nKritik açı aşılırsa tam yansıma olur (fiber optik).', 'Yoğuna geçen normale yaklaşır'),
  _k('kfiz-023', 'fizik', 'Optik', 'Aynalar ve mercekler', 'Çukur ayna ve ince kenarlı mercek ışığı toplar (yakınsak).\nTümsek ayna ve kalın kenarlı mercek ışığı dağıtır (ıraksak); her zaman düz, küçük, sanal görüntü verir.', 'Toplayan: çukur / ince kenarlı'),
  _k('kfiz-024', 'fizik', 'Optik', 'Işığın renkleri', 'Işığın ana renkleri kırmızı, yeşil, mavidir; üçü birleşince beyaz elde edilir.\nBoyaların ana renkleri: camgöbeği, eflatun (magenta), sarı.', 'RGB'),
  _k('kfiz-025', 'fizik', 'Momentum', 'Momentum ve itme', 'p = m · v (vektörel)\nİtme = F · Δt = Δp\nDış kuvvet yoksa toplam momentum korunur (çarpışma, patlama).', 'Kuvvet × süre'),
  _k('kfiz-026', 'fizik', 'Dairesel Hareket', 'Düzgün çembersel hareket', 'Merkezcil ivme a = v² / r, merkezcil kuvvet F = m·v² / r\nv = 2πr / T, f = 1 / T\nHız büyüklüğü sabit, yönü sürekli değişir.', 'v²/r'),
  _k('kfiz-027', 'fizik', 'Basit Harmonik Hareket', 'Basit sarkaç', 'Periyot T = 2π√(L / g)\nPeriyot kütleye ve (küçük açılarda) genliğe bağlı değildir; ip uzunluğuna ve yer çekimine bağlıdır.', 'Kütleden bağımsız'),
  _k('kfiz-028', 'fizik', 'Modern Fizik', 'Fotoelektrik olay', 'E_k(maks) = h·f − Φ (Φ: bağlanma enerjisi)\nEşik frekansın altında elektron sökülmez. Işık şiddeti elektron sayısını, frekans kinetik enerjiyi belirler.', 'Frekans belirler'),
  _k('kfiz-029', 'fizik', 'Atom Fiziği', 'Radyoaktif ışımalar', 'Alfa (α): helyum çekirdeği, girginliği en az\nBeta (β): elektron (ya da pozitron)\nGama (γ): yüksüz elektromanyetik dalga, girginliği en fazla\nYarılanma süresi: çekirdeklerin yarısının bozunduğu süre.', 'Gama en girgin'),
  _k('kfiz-030', 'fizik', 'Modern Fizik', 'Özel görelilik', 'Işığın boşluktaki hızı tüm gözlemciler için aynıdır (c ≈ 3·10⁸ m/s).\nHızla hareket edenin zamanı yavaşlar (zaman genişlemesi), boyu hareket yönünde kısalır.\nE = mc²', 'c sabit'),

  // ─── KİMYA ─────────────────────────────────────────────
  _k('kkim-001', 'kimya', 'Atom Modelleri', 'Atom modellerinin sırası', 'Dalton: içi dolu küre\nThomson: üzümlü kek (elektronlar pozitif küre içinde)\nRutherford: çekirdek keşfi (altın levha deneyi)\nBohr: elektronlar belirli enerji katmanlarında\nModern model: orbitaller (olasılık bulutu)', 'Dalton → Thomson → Rutherford → Bohr'),
  _k('kkim-002', 'kimya', 'Atomun Yapısı', 'İzotop, izoton, izobar', 'İzotop: proton sayısı aynı, nötron sayısı farklı (¹²C, ¹⁴C)\nİzoton: nötron sayısı aynı\nİzobar: kütle numarası aynı\nİzotopların kimyasal özellikleri aynıdır.', 'İzotop = proton aynı'),
  _k('kkim-003', 'kimya', 'Atomun Yapısı', 'Elektron dizilimi (Aufbau)', 'Orbitaller enerji sırasına göre dolar:\n1s 2s 2p 3s 3p 4s 3d 4p 5s …\ns: 2, p: 6, d: 10, f: 14 elektron alır.', '4s, 3d\'den önce'),
  _k('kkim-004', 'kimya', 'Periyodik Sistem', 'Periyodik özelliklerin değişimi', 'Soldan sağa: atom yarıçapı azalır; iyonlaşma enerjisi, elektronegatiflik ve ametal karakter artar.\nYukarıdan aşağı: atom yarıçapı ve metal karakter artar; iyonlaşma enerjisi azalır.', 'Sağ üst: F'),
  _k('kkim-005', 'kimya', 'Periyodik Sistem', 'Önemli gruplar', '1A: alkali metaller\n2A: toprak alkali metaller\n7A: halojenler\n8A: soygazlar (kararlı, tepkimeye girmeye isteksiz)\nB grupları: geçiş metalleri', '8A soygaz'),
  _k('kkim-006', 'kimya', 'Kimyasal Bağlar', 'Metalik bağ', 'Metal atomlarının değerlik elektronlarının oluşturduğu elektron denizi ile pozitif iyonlar arasındaki çekim.\nMetallerin elektrik ve ısı iletkenliği, parlaklığı ve işlenebilirliği bu bağdan kaynaklanır.', 'Elektron denizi'),
  _k('kkim-007', 'kimya', 'Etkileşimler', 'Zayıf etkileşimler', 'Van der Waals (London kuvvetleri: tüm moleküllerde; dipol-dipol: polar moleküllerde)\nHidrojen bağı: H\'nin F, O, N\'ye bağlı olduğu moleküller arasında; en güçlü zayıf etkileşimdir (suyun yüksek kaynama noktası).', 'FON + H'),
  _k('kkim-008', 'kimya', 'Kimyanın Temel Kanunları', 'Temel kanunlar', 'Kütlenin korunumu (Lavoisier): tepkimede toplam kütle değişmez.\nSabit oranlar (Proust): bir bileşikteki elementlerin kütlece oranı sabittir.\nKatlı oranlar (Dalton): aynı iki elementin farklı bileşiklerinde oranlar tam sayılarla ifade edilir.', 'Lavoisier-Proust-Dalton'),
  _k('kkim-009', 'kimya', 'Mol Kavramı', 'Mol hesaplamaları', 'n = m / M_A = N / Nₐ = V / 22,4 (NŞA\'da gaz)\nNₐ = 6,02 · 10²³ (Avogadro sayısı)', 'Kütle / mol kütlesi'),
  _k('kkim-010', 'kimya', 'Kimyasal Tepkimeler', 'Tepkime türleri', 'Yanma: O₂ ile tepkime\nSentez: basit maddelerden bileşik\nAnaliz: bileşiğin ayrışması\nNötralleşme: asit + baz → tuz + su\nÇözünme-çökelme: çözünmeyen katı oluşumu\nRedoks: elektron alışverişi', 'Asit + baz → tuz + su'),
  _k('kkim-011', 'kimya', 'Gazlar', 'İdeal gaz denklemi', 'P · V = n · R · T (T kelvin cinsinden)\nBoyle: sabit T\'de P·V sabit\nCharles: sabit P\'de V/T sabit\nGay-Lussac: sabit V\'de P/T sabit', 'Sıcaklık kelvin'),
  _k('kkim-012', 'kimya', 'Gazlar', 'Graham difüzyon yasası', 'Gazların yayılma hızı mol kütlesinin karekökü ile ters orantılıdır: v₁ / v₂ = √(M₂ / M₁)\nHafif gazlar daha hızlı yayılır.', 'Hafif hızlı'),
  _k('kkim-013', 'kimya', 'Çözeltiler', 'Derişim birimleri', 'Molarite: M = n / V(L)\nKütlece yüzde: (çözünen / çözelti) · 100\nppm: milyonda bir kısım (çok seyreltik çözeltiler)', 'M = mol / litre'),
  _k('kkim-014', 'kimya', 'Çözeltiler', 'Koligatif özellikler', 'Çözünen tanecik sayısına bağlı özellikler:\nKaynama noktası yükselmesi, donma noktası alçalması, buhar basıncı düşmesi, osmotik basınç.\nKışın yollara tuz serpilmesi donma noktası alçalmasına örnektir.', 'Tanecik sayısına bağlı'),
  _k('kkim-015', 'kimya', 'Çözeltiler', 'Çözünürlük ve sıcaklık', 'Katıların çoğunun sudaki çözünürlüğü sıcaklıkla artar.\nGazların sudaki çözünürlüğü sıcaklık artınca azalır, basınç artınca artar (gazoz açılınca köpürmesi).', 'Gaz: soğukta çok çözünür'),
  _k('kkim-016', 'kimya', 'Asitler ve Bazlar', 'pH ve pOH', '25 °C\'de pH + pOH = 14\npH < 7 asidik, pH = 7 nötr, pH > 7 bazik\npH = −log[H⁺]', 'pH + pOH = 14'),
  _k('kkim-017', 'kimya', 'Asitler ve Bazlar', 'Asit ve bazların özellikleri', 'Asit: suda H⁺ verir, mavi turnusolü kırmızıya çevirir, ekşi tatlıdır, aktif metallerle H₂ açığa çıkarır.\nBaz: suda OH⁻ verir, kırmızı turnusolü maviye çevirir, acı tatlı ve kayganlık hissi verir.', 'Asit → kırmızı turnusol'),
  _k('kkim-018', 'kimya', 'Tepkime Hızları', 'Aktifleşme enerjisi ve katalizör', 'Tepkimenin başlaması için gereken en düşük enerji aktifleşme enerjisidir.\nKatalizör aktifleşme enerjisini düşürür, hızı artırır; tepkime entalpisini ve denge konumunu değiştirmez.', 'Ea düşer, ΔH değişmez'),
  _k('kkim-019', 'kimya', 'Kimyasal Denge', 'Le Chatelier ilkesi', 'Dengedeki bir sisteme dış etki yapılırsa sistem bu etkiyi azaltacak yöne kayar.\nDerişim artışı: harcayan yöne\nBasınç artışı: az mol gaz yönüne\nSıcaklık: yalnızca K\'yi değiştiren etkendir.', 'Etkiye karşı koyar'),
  _k('kkim-020', 'kimya', 'Kimyasal Denge', 'Denge sabiti Kc', 'aA + bB ⇌ cC + dD için Kc = [C]ᶜ[D]ᵈ / [A]ᵃ[B]ᵇ\nSaf katı ve sıvılar ifadeye yazılmaz. Kc yalnızca sıcaklıkla değişir.', 'Ürünler / girenler'),
  _k('kkim-021', 'kimya', 'Redoks', 'Yükseltgenme ve indirgenme', 'Yükseltgenme: elektron verme, yükseltgenme basamağı artar.\nİndirgenme: elektron alma, basamak azalır.\nYükseltgenen madde indirgendir, indirgenen madde yükseltgendir.', 'Veren yükseltgenir'),
  _k('kkim-022', 'kimya', 'Elektrokimya', 'Pil ve elektroliz', 'Galvanik pil: kimyasal enerji → elektrik; anot (−) yükseltgenme, katot (+) indirgenme.\nElektroliz: elektrik enerjisiyle istemsiz tepkime; anot (+), katot (−).\nİki sistemde de anotta yükseltgenme olur.', 'Anot = yükseltgenme'),
  _k('kkim-023', 'kimya', 'Organik Kimya', 'Hidrokarbon türleri', 'Alkan: CₙH₂ₙ₊₂, tekli bağ (metan)\nAlken: CₙH₂ₙ, en az bir çift bağ (eten)\nAlkin: CₙH₂ₙ₋₂, en az bir üçlü bağ (etin/asetilen)\nAromatik: benzen halkası', 'Tek-çift-üçlü bağ'),
  _k('kkim-024', 'kimya', 'Organik Kimya', 'Fonksiyonel gruplar', 'Alkol: –OH\nAldehit: –CHO\nKeton: –CO– (karbonil, iki karbona bağlı)\nKarboksilik asit: –COOH\nEster: –COO–\nEter: –O–\nAmin: –NH₂', 'Asit = COOH'),
  _k('kkim-025', 'kimya', 'Organik Kimya', 'İzomeri', 'Aynı kapalı formüle sahip farklı yapıdaki bileşiklere izomer denir.\nÖrnek: C₂H₆O → etil alkol (CH₃CH₂OH) ve dimetil eter (CH₃OCH₃).', 'Aynı formül, farklı yapı'),
  _k('kkim-026', 'kimya', 'Madde ve Özellikleri', 'Ayırt edici özellikler', 'Maddeyi tanımlayan, miktara bağlı olmayan özellikler: özkütle, erime ve kaynama noktası, çözünürlük, esneklik, genleşme katsayısı.\nKütle ve hacim ayırt edici değildir.', 'Miktardan bağımsız'),
  _k('kkim-027', 'kimya', 'Karışımlar', 'Homojen ve heterojen karışım', 'Homojen (çözelti): her yerinde aynı özellik (tuzlu su, hava, alaşım)\nHeterojen: süspansiyon (katı-sıvı: tebeşir-su), emülsiyon (sıvı-sıvı: zeytinyağı-su), aerosol, kolloit', 'Emülsiyon = sıvı-sıvı'),
  _k('kkim-028', 'kimya', 'Enerji', 'Ekzotermik ve endotermik', 'Ekzotermik: ısı verir, ΔH < 0 (yanma, nötralleşme, donma, yoğuşma)\nEndotermik: ısı alır, ΔH > 0 (erime, buharlaşma, elektroliz)', 'Yanma ekzotermik'),
  _k('kkim-029', 'kimya', 'Polimerler', 'Polimerleşme', 'Küçük moleküllerin (monomer) birleşerek büyük zincirler (polimer) oluşturmasıdır.\nÖrnekler: polietilen (poşet), PVC, naylon; doğal polimerler: nişasta, selüloz, protein, DNA.', 'Monomer → polimer'),
  _k('kkim-030', 'kimya', 'Çekirdek Kimyası', 'Fisyon ve füzyon', 'Fisyon: ağır çekirdeğin bölünmesi (nükleer santral, uranyum-235)\nFüzyon: hafif çekirdeklerin birleşmesi (Güneş\'te hidrojenin helyuma dönüşmesi); daha fazla enerji açığa çıkar.', 'Güneş = füzyon'),

  // ─── BİYOLOJİ ──────────────────────────────────────────
  _k('kbiy-001', 'biyoloji', 'Sınıflandırma', 'Canlı âlemleri', 'Bakteriler, Arkeler (prokaryot)\nProtistler, Bitkiler, Mantarlar, Hayvanlar (ökaryot)\nVirüsler hücresel yapıda olmadığı için hiçbir âleme dahil edilmez.', 'Virüs âlem dışı'),
  _k('kbiy-002', 'biyoloji', 'Sınıflandırma', 'Prokaryot ve ökaryot hücre', 'Prokaryot: zarla çevrili çekirdek ve zarlı organel yok; DNA sitoplazmada (bakteri, arke).\nÖkaryot: çekirdek zarı ve zarlı organeller var.\nRibozom her iki hücrede de bulunur.', 'Ribozom ortak'),
  _k('kbiy-003', 'biyoloji', 'Temel Bileşenler', 'Karbonhidratlar', 'Monosakkarit: glikoz, fruktoz, galaktoz\nDisakkarit: maltoz, sükroz, laktoz (dehidrasyonla oluşur)\nPolisakkarit: nişasta (bitki), glikojen (hayvan, mantar), selüloz (bitki hücre çeperi), kitin', 'Glikojen hayvanda depo'),
  _k('kbiy-004', 'biyoloji', 'Temel Bileşenler', 'Proteinler', 'Yapı birimi amino asittir (20 çeşit). Amino asitler peptit bağıyla bağlanır.\nEnzim, hormon, antikor, taşıyıcı ve yapısal görevleri vardır. Yüksek sıcaklıkta yapısı bozulur (denatürasyon).', 'Peptit bağı'),
  _k('kbiy-005', 'biyoloji', 'Temel Bileşenler', 'Vitaminler', 'Yağda çözünenler: A, D, E, K (vücutta depolanabilir)\nSuda çözünenler: B grubu ve C (fazlası atılır, düzenli alınmalı)\nD vitamini deride güneş ışığıyla sentezlenir.', 'ADEK yağda'),
  _k('kbiy-006', 'biyoloji', 'Hücre', 'Hücre zarı', 'Akıcı mozaik model: çift katlı fosfolipit + proteinler + kolesterol + glikoprotein.\nSeçici geçirgendir. Glikoproteinler hücre tanınmasında görev alır.', 'Akıcı mozaik'),
  _k('kbiy-007', 'biyoloji', 'Hücre', 'Organellerin görevleri', 'Endoplazmik retikulum: madde taşınması (granüllü ER protein sentezine yardım)\nGolgi: paketleme ve salgılama\nLizozom: hücre içi sindirim\nKoful: depolama\nSentrozom: bölünmede iğ iplikleri (hayvan hücresi)', 'Golgi = paketleme'),
  _k('kbiy-008', 'biyoloji', 'Hücre', 'Osmoz, turgor ve plazmoliz', 'Osmoz: suyun seçici geçirgen zardan az yoğun ortamdan çok yoğun ortama geçişi.\nHipotonik ortamdaki bitki hücresi su alıp gerginleşir (turgor).\nHipertonik ortamda su kaybedip büzülür (plazmoliz).', 'Su, yoğun tarafa geçer'),
  _k('kbiy-009', 'biyoloji', 'Hücre Bölünmesi', 'Mitozun evreleri', 'İnterfaz: DNA eşlenir\nProfaz: kromozomlar belirginleşir, çekirdek zarı erir\nMetafaz: kromozomlar ekvatorda dizilir (kromozom sayımı için en uygun)\nAnafaz: kardeş kromatitler kutuplara çekilir\nTelofaz: çekirdek zarı yeniden oluşur', 'PMAT'),
  _k('kbiy-010', 'biyoloji', 'Üreme', 'Eşeysiz üreme türleri', 'Bölünme (bakteri, amip), tomurcuklanma (bira mayası, hidra), rejenerasyon (planarya), sporla üreme (mantar, eğrelti), vejetatif üreme (patates yumrusu, çilek stolonu), partenogenez (arı erkekleri).\nYavrular genetik olarak ataya benzer.', 'Çeşitlilik yok'),
  _k('kbiy-011', 'biyoloji', 'Kalıtım', 'Kalıtım terimleri', 'Gen: özelliği belirleyen DNA parçası\nAlel: aynı özelliğin farklı biçimleri (A / a)\nHomozigot (arı döl): AA veya aa\nHeterozigot (melez): Aa\nGenotip: gen yapısı, fenotip: dış görünüş', 'Aa = heterozigot'),
  _k('kbiy-012', 'biyoloji', 'Kalıtım', 'Eksik baskınlık ve eş baskınlık', 'Eksik baskınlık: heterozigotta ara fenotip (kırmızı × beyaz → pembe aslanağzı).\nEş baskınlık: iki alel de aynı anda kendini gösterir (AB kan grubu).', 'Pembe çiçek / AB'),
  _k('kbiy-013', 'biyoloji', 'Kalıtım', 'ABO kan grubu genotipleri', 'A: AA veya A0\nB: BB veya B0\nAB: AB\n0: 00\nA ve B alelleri 0\'a baskın, birbirine eş baskındır.', '0 çekinik'),
  _k('kbiy-014', 'biyoloji', 'Genetik', 'DNA\'nın yapısı', 'Çift zincirli sarmal (Watson-Crick). Nükleotit = deoksiriboz + fosfat + baz.\nA ile T (2 hidrojen bağı), G ile C (3 hidrojen bağı) eşleşir. A = T ve G = C.', 'G-C üç bağ'),
  _k('kbiy-015', 'biyoloji', 'Genetik', 'Genetik şifre', 'mRNA\'daki her üçlü baz (kodon) bir amino asidi belirler.\nBaşlama kodonu AUG, durdurma kodonları UAA, UAG, UGA.\nŞifre neredeyse tüm canlılarda ortaktır.', 'AUG başlatır'),
  _k('kbiy-016', 'biyoloji', 'Biyoteknoloji', 'Biyoteknoloji uygulamaları', 'Rekombinant DNA: bir canlının genini diğerine aktarma (bakteriye insan insülini ürettirme)\nPCR: DNA\'yı laboratuvarda çoğaltma\nGDO: genetiği değiştirilmiş organizma\nKlonlama: genetik kopya üretme', 'İnsülin üreten bakteri'),
  _k('kbiy-017', 'biyoloji', 'Ekoloji', 'Simbiyotik ilişkiler', 'Mutualizm: iki taraf da yararlanır (liken, baklagil-Rhizobium)\nKommensalizm: biri yararlanır, diğeri etkilenmez\nParazitizm: biri yararlanır, diğeri zarar görür (tenya, pire)', 'Liken = mutualizm'),
  _k('kbiy-018', 'biyoloji', 'Ekoloji', 'Karbon döngüsü', 'CO₂ fotosentezle organik maddeye bağlanır; solunum, yanma ve ayrıştırıcılarla atmosfere geri döner.\nFosil yakıtların yakılması atmosferdeki CO₂\'yi artırır (sera etkisi).', 'Fotosentez bağlar, solunum salar'),
  _k('kbiy-019', 'biyoloji', 'Sinir Sistemi', 'Sistemin bölümleri', 'Merkezî sinir sistemi: beyin ve omurilik\nÇevresel sinir sistemi: somatik (istemli) ve otonom (istemsiz)\nOtonom: sempatik (heyecan, kalp atışı hızlanır) ve parasempatik (dinlenme, yavaşlatır)', 'Sempatik = alarm'),
  _k('kbiy-020', 'biyoloji', 'Sinir Sistemi', 'Refleks yayı', 'Uyarı → duyu nöronu → omurilik (ara nöron) → motor nöron → tepki.\nBeyin karar vermeden hızlı ve istemsiz tepki oluşur (sıcak sobadan elini çekme).', 'Omurilik refleksi'),
  _k('kbiy-021', 'biyoloji', 'Endokrin Sistem', 'Önemli hormonlar', 'İnsülin (pankreas): kan şekerini düşürür\nGlukagon (pankreas): kan şekerini yükseltir\nTiroksin (tiroit): metabolizma hızı\nAdrenalin (böbrek üstü): stres, heyecan\nADH (hipofiz arka lobu): sudan tasarruf\nBüyüme hormonu (hipofiz ön lobu)', 'İnsülin düşürür'),
  _k('kbiy-022', 'biyoloji', 'Sindirim Sistemi', 'Sindirim enzimleri', 'Tükürük amilazı (ağız): nişasta\nPepsin (mide): protein\nPankreas: tripsin (protein), lipaz (yağ), amilaz (karbonhidrat)\nSafra enzim değildir; yağları küçük damlacıklara ayırır (emülsifikasyon).', 'Safra enzim değil'),
  _k('kbiy-023', 'biyoloji', 'Dolaşım Sistemi', 'Büyük ve küçük dolaşım', 'Küçük (akciğer) dolaşım: sağ karıncık → akciğer atardamarı → akciğer → akciğer toplardamarı → sol kulakçık\nBüyük dolaşım: sol karıncık → aort → vücut → üst/alt ana toplardamar → sağ kulakçık', 'Sol taraf oksijenli'),
  _k('kbiy-024', 'biyoloji', 'Bağışıklık', 'Aktif ve pasif bağışıklık', 'Aktif: vücut kendi antikorunu üretir (hastalık geçirme, aşı); kalıcıdır.\nPasif: hazır antikor alınır (serum, anne sütü, plasenta); geçicidir.', 'Aşı aktif, serum pasif'),
  _k('kbiy-025', 'biyoloji', 'Boşaltım Sistemi', 'İdrar oluşumu', 'Süzülme: glomerulustan Bowman kapsülüne\nGeri emilim: glikoz, amino asit, su ve tuzların kana geri alınması\nSalgılama: kandan tübüle atık aktarımı\nNefronda gerçekleşir.', 'Süz-emil-salgıla'),
  _k('kbiy-026', 'biyoloji', 'Duyu Organları', 'Göz ve görme', 'Retinada çubuk hücreler (az ışıkta görme, siyah-beyaz) ve koni hücreler (renkli görme) bulunur.\nSarı benekte koni yoğundur; kör noktada reseptör yoktur.\nMiyop: uzağı net göremez, kalın kenarlı (ıraksak) mercekle düzeltilir.\nHipermetrop: yakını net göremez, ince kenarlı (yakınsak) mercekle düzeltilir.', 'Koni = renk'),
  _k('kbiy-027', 'biyoloji', 'Bitki Biyolojisi', 'Bitki hormonları', 'Oksin: hücre uzaması, ışığa yönelme (fototropizma)\nSitokinin: hücre bölünmesi\nGiberellin: gövde uzaması, tohum çimlenmesi\nAbsisik asit: dormansi, stoma kapanması\nEtilen: meyve olgunlaşması', 'Etilen olgunlaştırır'),
  _k('kbiy-028', 'biyoloji', 'Enerji Dönüşümleri', 'Fotosentez hızını etkileyen etmenler', 'Işık şiddeti ve dalga boyu (kırmızı ve mavi ışık en etkili, yeşil en az), CO₂ miktarı, sıcaklık, su, mineral (Mg klorofil yapısında), klorofil miktarı ve stoma sayısı.', 'Yeşil ışık en az'),
  _k('kbiy-029', 'biyoloji', 'Enerji Dönüşümleri', 'Fermantasyon', 'Oksijensiz ortamda glikozun kısmen yıkılmasıdır; net 2 ATP elde edilir.\nEtil alkol fermantasyonu: maya (hamurun kabarması, CO₂ çıkar)\nLaktik asit fermantasyonu: yorgun kas, yoğurt bakterileri (CO₂ çıkmaz)', 'Net 2 ATP'),
  _k('kbiy-030', 'biyoloji', 'Evrim', 'Darwin ve doğal seçilim', 'Popülasyonda kalıtsal çeşitlilik vardır; ortama en uygun bireyler daha çok hayatta kalıp ürer ve özelliklerini aktarır.\nLamarck\'ın "kazanılmış özelliklerin kalıtımı" görüşü geçerli kabul edilmez.', 'En uygun olan hayatta kalır'),
];
